export const meta = {
  "slug": "frame",
  "name": "Frame",
  "family": "Layout",
  "collection": "Surfaces",
  "component": "createLinearFrame"
};

export function createLinearFrame(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderLinearScene(svg, current);
  };
  render();
  const controller = bindLinearScene(root, current);
  return {
    replay: controller.replay,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
  };
}
